# v3_ptmf.py -- TASK-20260930-610ee2 red-team-breakthrough review computation.
# ZERO RUNS of EXP-BINSTD-178742. Toy-size instrument only.
# Implements CERT-BIND / CERT-QUOT as written in EXP-BINSTD-178742 version 3
# (RD-1 projected bind; RD-2 sealed-vector = ranked-vector) and re-runs:
#   J-RD1: unmutated G4 control at (17,0), including targets outside G
#   J-RD2 / PTM-F: M3 and planted F-i / F-ii vs sealed CERT-QUOT
# Contrasts withdrawn R-lit / R-piG-label-only readings (prior B1/B2) to show
# the repair changes the gate outcomes. Seeds reused from prior review for
# reproducibility of cell geometry, not as citation of prior outcomes.
import json, time, random, sys
from collections import Counter, defaultdict
sys.path.insert(0, '/tmp/rt610ee2')
from e4lib import *
from e4j3 import (
    Sub, draw, esum, relations, build, quot_row, cert_label, cert_bind,
    fpolys, ar1, ranks, polyeval, rank_A, rank_B
)

T0 = time.time()
SEED_PREFIX = 'RT-610ee2-V3|'

def v3_seal(sub, labels):
    """CERT-QUOT seal: coefficient vector from CERT-LABEL labels at AR-2 lambda."""
    return quot_row(sub, labels, sub.lam)

def v3_cert_quot(sub, labels, R, Q, ranked_vector):
    """
    V3 CERT-QUOT:
      (1) sealed v from labels at lambda; require ranked_vector == sealed entrywise
      (2) v_O ≡ f_O(lambda) (sealed is built that way)
      (3) sum [v_O] Q_O = pi_G(R) on the curve, using the sealed (true) equation
    Ranking a vector CERT-QUOT did not seal -> IR-15 before any rank readout.
    Returns (ok, detail).
    """
    sealed = v3_seal(sub, labels)
    # entrywise equality on the union of keys
    keys = set(sealed) | set(ranked_vector)
    for o in keys:
        if (sealed.get(o, 0) % sub.r) != (ranked_vector.get(o, 0) % sub.r):
            return False, 'ranked_vector != CERT-QUOT-sealed vector (IR-15)'
    # on-curve check on the sealed equation
    S = None
    for o, v in sealed.items():
        if v % sub.r:
            S = sub.c.E.add(S, sub.c.smul(v % sub.r, Q[o]))
    if S != sub.c.piG(R):
        return False, 'sealed equation fails on-curve sum[v_O]Q_O = pi_G(R) (IR-15)'
    return True, 'pass'

def v3_cert_bind(sub, j, B, R, Q):
    """V3 CERT-BIND: projected identity on G / pi_G(R). Returns None or detail."""
    return cert_bind(sub, j, B, R, 'R-piG', Q)  # e4j3 R-piG branch IS the projected identity

def v3_p22b(sub, B, R, Q, ranked_override=None):
    """
    P2-2b under v3: CERT-LABEL row0 -> CERT-QUOT seal+rank-eq -> CERT-BIND j=1..k-1.
    ranked_override: if set, the vector presented to RANK (plant / M3); else sealed.
    """
    L0, lab0 = B['rows'][0]
    for P, lb in zip(L0, lab0):
        if not cert_label(sub, P, lb, Q):
            return ('IR-16', 'CERT-LABEL row 0')
    sealed = v3_seal(sub, lab0)
    ranked = ranked_override if ranked_override is not None else sealed
    # M3-style: instrument builds ranked at B['z'] which may be laminv
    if ranked_override is None and B.get('z') != sub.lam:
        ranked = quot_row(sub, lab0, B['z'])
    ok, detail = v3_cert_quot(sub, lab0, R, Q, ranked)
    if not ok:
        return ('IR-15', detail)
    for j in range(1, sub.k):
        d = v3_cert_bind(sub, j, B, R, Q)
        if d:
            return ('IR-17', 'CERT-BIND j=%d: %s' % (j, d))
    return None

def withdrawn_p22b(sub, B, R, Q, mode):
    """Prior failure-mode readings for contrast only (not the v3 gate)."""
    L0, lab0 = B['rows'][0]
    for P, lb in zip(L0, lab0):
        if not cert_label(sub, P, lb, Q):
            return ('IR-16', 'CERT-LABEL row 0')
    if mode == 'R-lit':
        # literal CERT-QUOT from labels (always true equation); literal CERT-BIND
        S = None
        coeffs = quot_row(sub, lab0, sub.lam)
        for o, v in coeffs.items():
            if v % sub.r:
                S = sub.c.E.add(S, sub.c.smul(v % sub.r, Q[o]))
        if S != sub.c.piG(R):
            return ('IR-15', 'CERT-QUOT')
        for j in range(1, sub.k):
            d = cert_bind(sub, j, B, R, 'R-lit', Q)
            if d:
                return ('IR-17', 'CERT-BIND j=%d: %s' % (j, d))
        return None
    if mode == 'R-piG-label-only':
        # projected CERT-BIND; CERT-QUOT only on label-derived vector (ignores ranked)
        S = None
        coeffs = quot_row(sub, lab0, sub.lam)
        for o, v in coeffs.items():
            if v % sub.r:
                S = sub.c.E.add(S, sub.c.smul(v % sub.r, Q[o]))
        if S != sub.c.piG(R):
            return ('IR-15', 'CERT-QUOT')
        for j in range(1, sub.k):
            d = cert_bind(sub, j, B, R, 'R-piG', Q)
            if d:
                return ('IR-17', 'CERT-BIND j=%d: %s' % (j, d))
        return None
    raise ValueError(mode)

def g4_v3(sub, rels, instr):
    """G4 under v3 certificates. Mutants M1/M2/M3 must be invalidated; control pass."""
    def one(build_instr, base):
        nf = 0; first = None; adm = 0; outside = 0; outside_fail = 0
        for (src, legs, R) in rels:
            if ar1(sub, legs, R):
                continue
            adm += 1
            if sub.c.piG(R) != R:
                outside += 1
            B = build(sub, base, legs)
            if build_instr == 'M1':
                B['rows'] = [B['rows'][0]] * sub.k
            if build_instr == 'M2':
                B['rows'] = [(L, [(o, (-e) % sub.k, eps) for (o, e, eps) in labs])
                             for (L, labs) in B['rows']]
            if build_instr == 'M3':
                B['z'] = sub.c.laminv
            f = v3_p22b(sub, B, R, sub.QO)
            if f:
                nf += 1
                first = first or f
                if sub.c.piG(R) != R:
                    outside_fail += 1
        return {'failures': nf, 'admitted': adm, 'first': first,
                'targets_outside_G': outside, 'outside_G_failures': outside_fail}

    ctrl = one('base', instr)
    m1 = one('M1', instr)
    m2 = one('M2', instr)
    m3 = one('M3', instr)
    passed = (ctrl['failures'] == 0 and m1['failures'] > 0 and m2['failures'] > 0 and m3['failures'] > 0)
    return passed, {'CONTROL': ctrl, 'M1': m1, 'M2': m2, 'M3': m3}

def planted_rank(sub, qrow, orbs):
    rows = [[(pow(sub.lam, j, sub.r) * qrow.get(o, 0)) % sub.r for o in orbs]
            for j in range(sub.k)]
    return rank_A(rows, sub.r), rank_B(rows, sub.r)

out = {'task': 'TASK-20260930-610ee2', 'nature': 'review_computation_zero_runs',
       'certificate_rule': 'v3 CERT-BIND projected; v3 CERT-QUOT sealed==ranked'}

# ---- cells ----
cells_info = {}
subs = {}
for (n, a) in [(17, 0), (17, 1), (23, 0)]:
    s = Sub(n, a)
    subs[(n, a)] = s
    cells_info['(%d,%d)' % (n, a)] = {
        'r': s.r, 'h': s.c.h, 'lambda': s.lam, 'lambda_inv': s.c.laminv,
        'k': s.k, '|F_W|': len(s.FW), 'class_orbits': len(s.QO),
        'FW_in_G': sum(1 for P in s.FW if s.c.piG(P) == P),
    }
out['cells'] = cells_info
print('CELLS', json.dumps(cells_info))

# ---- J-RD1 / G4 at (17,0) ----
s0 = subs[(17, 0)]
rng = random.Random(subseed('G4-RS3-m2-17-0'))  # same geometry seed as prior for cell (17,0)
g4rels = []
for _ in range(16):
    L = draw(s0, rng, 2)
    g4rels.append(('RS-3m2', L, esum(s0.c.E, L)))
admitted = [(src, L, R) for (src, L, R) in g4rels if not ar1(s0, L, R)]
outside = sum(1 for (_, _, R) in admitted if s0.c.piG(R) != R)
print('G4 pool: drawn', len(g4rels), 'admitted', len(admitted), 'outside_G', outside)

passed, g4info = g4_v3(s0, g4rels, 'CONTROL')
# also contrast withdrawn readings on CONTROL only
contrast = {}
for mode in ('R-lit', 'R-piG-label-only'):
    nf = 0; first = None; adm = 0
    for (src, legs, R) in g4rels:
        if ar1(s0, legs, R):
            continue
        adm += 1
        B = build(s0, 'CONTROL', legs)
        f = withdrawn_p22b(s0, B, R, s0.QO, mode)
        if f:
            nf += 1
            first = first or f
    contrast[mode] = {'CONTROL_failures': nf, 'admitted': adm, 'first': first,
                      'CONTROL_passes_G4_alone': nf == 0}

out['J_RD1_G4'] = {
    'cell': '(17,0)',
    'v3_gate_passed': passed,
    'v3_detail': g4info,
    'withdrawn_readings_CONTROL_only': contrast,
    'attack_note': (
        'Prior B1: R-lit rejects unmutated control (unprojected CERT-BIND). '
        'V3 projected CERT-BIND must let CONTROL pass including outside-G targets; '
        'M1 must still fail CERT-BIND; M3 must fail CERT-QUOT.'
    ),
}
print('J-RD1 G4 v3 PASS' if passed else 'J-RD1 G4 v3 FAIL', json.dumps(g4info))
print('J-RD1 contrast', json.dumps(contrast))

# ---- J-RD2 / PTM-F ----
ptmf = {}
for cell in [(17, 1), (23, 0)]:
    sb = subs[cell]
    rels = [x for x in relations(sb, 'PTMF-%d-%d' % cell, nrs1=4, n3=4, n4=0)
            if not ar1(sb, x[1], x[2])]
    picked = ([x for x in rels if sb.c.piG(x[2]) == x[2]][:3]
              + [x for x in rels if sb.c.piG(x[2]) != x[2]][:2])
    cell_rows = []
    for (src, L, R) in picked:
        B = build(sb, 'CONTROL', L)
        lab0 = B['rows'][0][1]
        f = quot_row(sb, lab0, sb.lam)
        fi = quot_row(sb, lab0, sb.c.laminv)
        orbs = sorted(f)
        o_i = orbs[0]
        o_ii = next((o for o in orbs if fi[o] != f[o]), None)
        plants = {
            'unmutated_control': dict(f),
            'F-i': dict(f),
        }
        plants['F-i'][o_i] = (f[o_i] + 1) % sb.r
        if o_ii is not None:
            plants['F-ii'] = dict(f)
            plants['F-ii'][o_ii] = fi[o_ii]
        row_out = {'src': src, 'target_in_G': sb.c.piG(R) == R, 'hit_orbits': len(orbs),
                   'plants': {}}
        for name, q in plants.items():
            ra, rb = planted_rank(sb, q, orbs)
            # v3: seal from labels; ranked = planted q
            fail = v3_p22b(sb, B, R, sb.QO, ranked_override=q)
            # withdrawn R-piG-label-only: CERT-QUOT ignores planted ranked vector
            w = withdrawn_p22b(sb, B, R, sb.QO, 'R-piG-label-only')
            if fail is None:
                v3_verdict = 'ACCEPTED (proves-too-much if plant)'
            else:
                v3_verdict = 'INVALIDATED by %s: %s' % fail
            if w is None:
                withdrawn_verdict = 'ACCEPTED under label-only CERT-QUOT (prior B2 gap)'
            else:
                withdrawn_verdict = 'INVALIDATED by %s: %s' % w
            S_ranked = None
            for o, v in q.items():
                if v % sb.r:
                    S_ranked = sb.c.E.add(S_ranked, sb.c.smul(v % sb.r, sb.QO[o]))
            row_out['plants'][name] = {
                'rank_A': ra, 'rank_B': rb,
                'v3_CERT_QUOT_vs_ranked': v3_verdict,
                'withdrawn_R_piG_label_only': withdrawn_verdict,
                'on_curve_identity_for_ranked_vector': S_ranked == sb.c.piG(R),
            }
        # M3 on same relation under v3
        B3 = build(sb, 'M3', L)
        m3fail = v3_p22b(sb, B3, R, sb.QO)
        row_out['M3_v3'] = ('PASS' if m3fail is None else 'INVALIDATED by %s: %s' % m3fail)
        cell_rows.append(row_out)
    ptmf['(%d,%d)' % cell] = cell_rows
    print('PTM-F', cell, 'n_rels', len(cell_rows))
    for row in cell_rows:
        print(' ', row['src'], 'inG', row['target_in_G'],
              {k: v['v3_CERT_QUOT_vs_ranked'] for k, v in row['plants'].items()},
              'M3', row['M3_v3'])

out['J_RD2_PTM_F'] = ptmf

# ---- signature summary ----
sig = {
    'PTM_F_failure_signature': (
        'PTM-F MUST be INVALIDATED by repaired CERT-QUOT before any rank readout, '
        'while unmutated control PASSES G4 under repaired CERT-BIND.'
    ),
    'G4_v3_CONTROL_pass': passed,
    'G4_v3_CONTROL_outside_G_failures': g4info['CONTROL']['outside_G_failures'],
    'G4_v3_M1_invalidated': g4info['M1']['failures'] == g4info['M1']['admitted'],
    'G4_v3_M3_invalidated': g4info['M3']['failures'] == g4info['M3']['admitted'],
}
ctrl_ok = True
plants_invalidated = True
m3_invalidated = True
n_ctrl = n_fi = n_fii = n_m3 = 0
for cell_rows in ptmf.values():
    for row in cell_rows:
        n_ctrl += 1
        if 'ACCEPTED' not in row['plants']['unmutated_control']['v3_CERT_QUOT_vs_ranked']:
            ctrl_ok = False
        if 'INVALIDATED' not in row['plants']['F-i']['v3_CERT_QUOT_vs_ranked']:
            plants_invalidated = False
        n_fi += 1
        if 'F-ii' in row['plants']:
            n_fii += 1
            if 'INVALIDATED' not in row['plants']['F-ii']['v3_CERT_QUOT_vs_ranked']:
                plants_invalidated = False
        n_m3 += 1
        if not row['M3_v3'].startswith('INVALIDATED'):
            m3_invalidated = False
sig.update({
    'PTM_F_unmutated_control_accepted_all': ctrl_ok,
    'PTM_F_plants_invalidated_all': plants_invalidated,
    'M3_invalidated_all': m3_invalidated,
    'counts': {'controls': n_ctrl, 'F-i': n_fi, 'F-ii': n_fii, 'M3': n_m3},
    'signature_met': bool(passed and ctrl_ok and plants_invalidated and m3_invalidated
                          and g4info['CONTROL']['outside_G_failures'] == 0),
})
out['signature'] = sig
out['elapsed_s'] = round(time.time() - T0, 1)
print('SIGNATURE', json.dumps(sig))
print('elapsed_s', out['elapsed_s'])
Path = __import__('pathlib').Path
Path('/tmp/rt610ee2/v3_ptmf_out.json').write_text(json.dumps(out, indent=2, default=str))
print('wrote /tmp/rt610ee2/v3_ptmf_out.json')

