# e4lib.py -- epoch-4 red-team REVIEW COMPUTATION library (TASK-20260925-2333ea).
# Written from the text of EXP-BINSTD-178742 v2 (definitions, certificates,
# procedure) only; the epoch-2 scripts were not consulted when writing it.
# Toy sizes only. No solver of any kind. Python stdlib + sympy (factorint,
# isprime, sqrt_mod, GF(2) polynomial factorisation, DomainMatrix rank).
import hashlib, random
from functools import lru_cache
import sympy
from sympy import factorint, isprime
from sympy.ntheory import sqrt_mod
from sympy.polys.matrices import DomainMatrix
from sympy.polys.domains import GF as SGF

def subseed(label):
    return int.from_bytes(hashlib.sha256(('RT-2333ea-E4|' + label).encode()).digest(), 'big')

# ---------------- GF(2)[X] integer-bit polynomials ----------------
def pdeg(a): return a.bit_length() - 1
def pmul(a, b):
    r = 0
    while b:
        if b & 1: r ^= a
        a <<= 1; b >>= 1
    return r
def pmod(a, m):
    dm = pdeg(m)
    while a and pdeg(a) >= dm:
        a ^= m << (pdeg(a) - dm)
    return a
def pgcd(a, b):
    while b: a, b = b, pmod(a, b)
    return a
def is_irred(f):
    # Rabin-style: X^(2^n) = X mod f and gcd(X^(2^(n/p)) - X, f) = 1
    n = pdeg(f)
    def xpow2k(k):
        t = 2
        for _ in range(k): t = pmod(pmul(t, t), f)
        return t
    if xpow2k(n) != 2: return False
    for p in factorint(n):
        if pgcd(xpow2k(n // p) ^ 2, f) != 1: return False
    return True
def field_poly(n):
    # lowest weight, then least as an integer (spec field_representation recommendation)
    for w in (3, 5, 7):
        cands = []
        from itertools import combinations
        for mids in combinations(range(1, n), w - 2):
            f = (1 << n) | 1
            for i in mids: f |= 1 << i
            cands.append(f)
        for f in sorted(cands):
            if is_irred(f): return f
    raise ValueError(n)

# ---------------- F_{2^n} ----------------
class F2n:
    def __init__(self, n, poly=None):
        self.n = n; self.poly = poly or field_poly(n); self.mask = (1 << n) - 1
    def mul(self, a, b):
        r = 0
        while b:
            if b & 1: r ^= a
            b >>= 1; a <<= 1
            if a >> self.n: a ^= self.poly
        return r
    def sqr(self, a): return self.mul(a, a)
    def inv(self, a):
        if a == 0: raise ZeroDivisionError
        u, v, g1, g2 = a, self.poly, 1, 0
        while u != 1:
            j = pdeg(u) - pdeg(v)
            if j < 0: u, v, g1, g2 = v, u, g2, g1; j = -j
            u ^= v << j; g1 ^= g2 << j
        return pmod(g1, self.poly)
    def pw(self, a, e):
        r = 1
        while e:
            if e & 1: r = self.mul(r, a)
            a = self.mul(a, a); e >>= 1
        return r
    def frob(self, a, j):
        for _ in range(j % self.n): a = self.sqr(a)
        return a
    def trace(self, a):
        t, s = a, a
        for _ in range(self.n - 1):
            s = self.sqr(s); t ^= s
        return t
    def halftrace(self, a):
        assert self.n % 2 == 1
        t, s = a, a
        for _ in range((self.n - 1) // 2):
            s = self.sqr(self.sqr(s)); t ^= s
        return t
    def sqrt(self, a): return self.frob(a, self.n - 1)

# ---------------- curve y^2 + xy = x^3 + a x^2 + b ----------------
class Curve:
    def __init__(self, F, a, b):
        self.F, self.a, self.b = F, a, b
    def on(self, P):
        if P is None: return True
        F = self.F; x, y = P
        return F.sqr(y) ^ F.mul(x, y) == F.mul(F.sqr(x), x) ^ F.mul(self.a, F.sqr(x)) ^ self.b
    def neg(self, P):
        return None if P is None else (P[0], P[0] ^ P[1])
    def add(self, P, Q):
        F = self.F
        if P is None: return Q
        if Q is None: return P
        x1, y1 = P; x2, y2 = Q
        if x1 == x2:
            if y1 ^ y2 == x2: return None          # Q = -P
            if x1 == 0: return None               # 2-torsion doubling
            lam = x1 ^ F.mul(y1, F.inv(x1))
            x3 = F.sqr(lam) ^ lam ^ self.a
            y3 = F.sqr(x1) ^ F.mul(lam ^ 1, x3)
            return (x3, y3)
        lam = F.mul(y1 ^ y2, F.inv(x1 ^ x2))
        x3 = F.sqr(lam) ^ lam ^ x1 ^ x2 ^ self.a
        y3 = F.mul(lam, x1 ^ x3) ^ x3 ^ y1
        return (x3, y3)
    def mulk(self, k, P):
        if k < 0: return self.mulk(-k, self.neg(P))
        R = None
        while k:
            if k & 1: R = self.add(R, P)
            P = self.add(P, P); k >>= 1
        return R
    def tau(self, P, j=1):
        return None if P is None else (self.F.frob(P[0], j), self.F.frob(P[1], j))
    def lift_x(self, x):
        """all points with this x (0, 1 or 2)"""
        F = self.F
        if x == 0: return [(0, F.sqrt(self.b))]
        c = x ^ self.a ^ F.mul(self.b, F.inv(F.sqr(x)))
        if F.trace(c) != 0: return []
        z = F.halftrace(c)
        return [(x, F.mul(x, z)), (x, F.mul(x, z ^ 1))]

def lucas_order(n, a):
    t = 1 if a == 1 else -1
    s0, s1 = 2, t
    for _ in range(n - 1): s0, s1 = s1, t * s1 - 2 * s0
    return 2 ** n + 1 - s1

# ---------------- Koblitz cell ----------------
class Cell:
    def __init__(self, n, a, seedlabel):
        self.n, self.a = n, a
        self.F = F2n(n); self.E = Curve(self.F, a, 1)
        self.N = lucas_order(n, a)
        fac = factorint(self.N); self.fac = fac
        self.r = max(fac); self.h = self.N // self.r
        self.k = n; self.t = 1 if a == 1 else -1
        self.proj = self.h * pow(self.h, -1, self.r)       # pi_G scalar
        rng = random.Random(subseed(seedlabel))
        # generator P0 of G
        while True:
            x = rng.getrandbits(n)
            pts = self.E.lift_x(x)
            if not pts: continue
            P0 = self.E.mulk(self.proj, pts[0])
            if P0 is not None: break
        self.P0 = P0
        assert self.E.mulk(self.r, P0) is None
        disc = (self.t * self.t - 8) % self.r
        roots = set()
        for s in sqrt_mod(disc, self.r, all_roots=True):
            roots.add(((self.t + s) * pow(2, -1, self.r)) % self.r)
        lam = [l for l in roots if self.E.mulk(l, P0) == self.E.tau(P0)]
        assert len(lam) == 1
        self.lam = lam[0]; self.laminv = pow(self.lam, -1, self.r)
        self.ord_lam = min(d for d in sympy.divisors(self.r - 1) if pow(self.lam, d, self.r) == 1)
    def piG(self, P): return _mul_cached(self.E, self.proj, P)
    def smul(self, s, P): return _mul_cached(self.E, s, P)

_cache = {}
def _mul_cached(E, s, P):
    key = (id(E), s, P)
    v = _cache.get(key)
    if v is None and key not in _cache:
        v = E.mulk(s, P); _cache[key] = v
    return v

# ---------------- F_2 linear algebra: kernel of g(tau) ----------------
def kernel_of_linearised(F, g):
    """W = {x : sum_i g_i x^(2^i) = 0}; returns list of all elements."""
    n = F.n
    cols = []
    for i in range(n):
        x = 1 << i; acc = 0; s = x; gi = g; e = 0
        while gi:
            if gi & 1: acc ^= s
            s = F.sqr(s); gi >>= 1
        cols.append(acc)
    # solve M v = 0 over F_2, M columns = cols (bit j of cols[i] = M[j][i])
    rows = [sum(((cols[i] >> j) & 1) << i for i in range(n)) for j in range(n)]
    # gaussian elimination on rows (each an n-bit int over variables)
    piv = {}; red = []
    for rw in rows:
        for p, prw in piv.items():
            if (rw >> p) & 1: rw ^= prw
        if rw:
            p = rw.bit_length() - 1
            for q in list(piv):
                if (piv[q] >> p) & 1: piv[q] ^= rw
            piv[p] = rw
    free = [i for i in range(n) if i not in piv]
    basis = []
    for f in free:
        v = 1 << f
        for p, prw in piv.items():
            if (prw >> f) & 1: v |= 1 << p
        basis.append(v)
    elems = [0]
    for b in basis: elems = elems + [e ^ b for e in elems]
    return basis, elems

def phi_factors(n):
    X = sympy.symbols('X')
    phi = sum(X ** i for i in range(n))
    fl = sympy.Poly(phi, X, modulus=2).factor_list()[1]
    ints = []
    for f, e in fl:
        assert e == 1
        cs = [int(c) % 2 for c in f.all_coeffs()]
        v = 0
        for c in cs: v = (v << 1) | c
        ints.append(v)
    return sorted(ints)

# ---------------- F_r linear algebra ----------------
def rank_A(M, r):
    """hand-written Gaussian elimination mod r (RANK-A)"""
    A = [[x % r for x in row] for row in M]
    rk = 0; ncols = len(A[0]) if A else 0
    for c in range(ncols):
        p = next((i for i in range(rk, len(A)) if A[i][c]), None)
        if p is None: continue
        A[rk], A[p] = A[p], A[rk]
        iv = pow(A[rk][c], -1, r)
        A[rk] = [(x * iv) % r for x in A[rk]]
        for i in range(len(A)):
            if i != rk and A[i][c]:
                f = A[i][c]; A[i] = [(x - f * y) % r for x, y in zip(A[i], A[rk])]
        rk += 1
    return rk

def rank_B(M, r):
    """library routine: sympy DomainMatrix over GF(r) (RANK-B)"""
    if not M or not M[0]: return 0
    D = DomainMatrix([[SGF(r)(x % r) for x in row] for row in M], (len(M), len(M[0])), SGF(r))
    return D.rank()

def polyeval(coeffs, z, r):
    """coeffs: dict e -> c; value sum c z^e mod r"""
    return sum(c * pow(z, e, r) for e, c in coeffs.items()) % r
